('yoga','יוגה','https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Shiva_Bangalore.jpg/500px-Shiva_Bangalore.jpg','https://commons.wikimedia.org/wiki/File:Shiva_Bangalore.jpg'),
('massage','עיסוי','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Thaimassage.jpg/500px-Thaimassage.jpg','https://commons.wikimedia.org/wiki/File:Thaimassage.jpg'),
('tour','סיור','https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Tour_Guide.jpg/500px-Tour_Guide.jpg','https://commons.wikimedia.org/wiki/File:Tour_Guide.jpg'),
