('hobby','תחביב','https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/Fran%C3%A7ois_Barraud_-_Le_Philat%C3%A9liste.jpg/500px-Fran%C3%A7ois_Barraud_-_Le_Philat%C3%A9liste.jpg','https://commons.wikimedia.org/wiki/File:François_Barraud_-_Le_Philatéliste.jpg')
)
update public.content_items c set image_url = m.url, image_credit = m.credit, updated_at = now()
from m
where c.item_type = 'word' and (
  (c.learning_language = 'en' and c.source_text = m.en) or
  (c.learning_language = 'th' and c.translation_language = 'he' and c.translation_text = m.he) or
  (c.learning_language = 'he' and c.source_text = m.he)
);
select learning_language, translation_language, count(*) filter (where image_url is not null) as with_image, count(*) as words from public.content_items where item_type = 'word' group by 1,2 order by 1,2;